"%% model.m — mc_01: Monte Carlo robustness screening (closed-loop short-period spec)
% Nominal longitudinal 4-state model x = [u, w, q, theta], elevator state
% feedback u = -K*x with the nominal short-period placed at wn = 2.0 rad/s,
% zeta = 0.6 and the phugoid held at its open-loop locations.
% Monte Carlo over +/-25% uniform uncertainty in Mw, Zw, Mq (N = 200
% deterministic samples drawn with the prescribed independent seeds).

clear; clc;

%% Nominal longitudinal model
Vn = 710.0;
Xu = -0.0066;   Xw =  0.039;
Zu = -0.032;    Zw = -0.72;
Mw = -0.0053;   Mq = -0.9;
g0 = 32.174;

A = [ Xu   Xw   0    -g0  ;
      Zu   Zw   Vn    0   ;
      0    Mw   Mq    0   ;
      0    0    1     0   ];

B = [0; -6.0; -4.0; 0];

%% Gain design: short-period at wn = 2.0, zeta = 0.6; phugoid kept open-loop
wn_d   = 2.0;
zeta_d = 0.6;
sp_des = [ -zeta_d*wn_d + 1i*wn_d*sqrt(1 - zeta_d^2) ;
           -zeta_d*wn_d - 1i*wn_d*sqrt(1 - zeta_d^2) ];

ol_poles = eig(A);
[~, ord] = sort(abs(ol_poles), 'ascend');   % phugoid = lowest-|lambda| pair
phug_des = ol_poles(ord(1:2));

K = place(A, B, [sp_des; phug_des]);
Acl_nom  = A - B*K;

% nominal verification (diagnostic only)
ev_nom = eig(Acl_nom);
[~, ixn] = sort(abs(ev_nom), 'descend');
wn_nom = abs(ev_nom(ixn(1)));
zt_nom = -real(ev_nom(ixn(1)))/wn_nom;
fprintf('K = [%.6g %.6g %.6g %.6g]\n', K);
fprintf('Nominal closed-loop short-period: wn = %.4f rad/s, zeta = %.4f\n', wn_nom, zt_nom);

%% Monte Carlo setup: N = 200 deterministic samples, +/-25% uniform box
N   = 200;
pct = 0.25;

rng(20260827); f_Mw = 1 + pct*(2*rand(N,1) - 1);
rng(20261827); f_Zw = 1 + pct*(2*rand(N,1) - 1);
rng(20262827); f_Mq = 1 + pct*(2*rand(N,1) - 1);

%% Spec screening: wn in [1.88, 2.12] rad/s AND zeta >= 0.51
wn_lo   = 1.88;
wn_hi   = 2.12;
zeta_lo = 0.51;

count      = 0;
wn_hist    = zeros(N,1);
zeta_hist  = zeros(N,1);

for i = 1:N
    Ai = A;
    Ai(2,2) = Zw * f_Zw(i);
    Ai(3,2) = Mw * f_Mw(i);
    Ai(3,3) = Mq * f_Mq(i);

    ev = eig(Ai - B*K);
    [~, idx] = sort(abs(ev), 'descend');   % short-period = largest-|lambda| pair
    lam = ev(idx(1));

    wn_i   = abs(lam);
    zeta_i = -real(lam)/max(wn_i, eps);

    wn_hist(i)   = wn_i;
    zeta_hist(i) = zeta_i;

    if (wn_i >= wn_lo) && (wn_i <= wn_hi) && (zeta_i >= zeta_lo)
        count = count + 1;
    end
end

pass_fraction      = count/N;
failing_case_count = N - count;

fprintf('MC short-period: wn in [%.4f, %.4f], zeta in [%.4f, %.4f]\n', ...
        min(wn_hist), max(wn_hist), min(zeta_hist), max(zeta_hist));
fprintf('pass_fraction = %.4f  (%d / %d)\n', pass_fraction, count, N);
fprintf('failing_case_count = %d\n', failing_case_count);

%% Write result.json (jsonencode of top-level struct with required keys)
result = struct('pass_fraction', pass_fraction, 'failing_case_count', failing_case_count);

fid = fopen('result.json', 'w');
if fid == -1
    error('model:FileOpen', 'Cannot open result.json for writing.');
end
fwrite(fid, jsonencode(result), 'char');
fclose(fid);"
